import {spawnSync} from 'node:child_process';
const r=spawnSync(process.execPath,['--test','--test-concurrency=1','tests/goal0.test.mjs'],{stdio:'inherit',timeout:175000});if(r.error)console.error(r.error.message);process.exitCode=r.status??1;
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile,writeFile,mkdir,mkdtemp} from 'node:fs/promises';
import path from 'node:path';
import {createRequire} from 'node:module';
import {spawn} from 'node:child_process';
import {Store} from '../src/adapters/store.mjs';
import {createServer} from '../src/server/server.mjs';
import {searchBooks,counts} from '../src/domain/books.mjs';
const evidence=path.resolve('validation/goal0');await mkdir(evidence,{recursive:true});await mkdir('var/tests',{recursive:true});
const seed=JSON.parse(await readFile('data/seed.json','utf8'));const requests=[],actions=[];
async function fixture(opts={}){const dir=await mkdtemp(path.resolve('var/tests/run-'));const store=new Store(dir,opts);await store.init();return {dir,store};}
async function start(store){const server=createServer(store);await new Promise(r=>server.listen(0,'127.0.0.1',r));return {server,url:`http://127.0.0.1:${server.address().port}`};}
async function stop(server){await new Promise(r=>server.close(r));}
async function patch(url,body,extra={}){const r=await fetch(url+'/api/books/B-001/engineering-note',{method:'PATCH',headers:{'Content-Type':'application/json',...extra},body:JSON.stringify(body)});return {status:r.status,body:await r.json()};}
test('AC-002/003/004 domain counts and search',()=>{assert.deepEqual(counts(seed.books),{total:3,available:2,borrowed:1});assert.equal(searchBooks(seed.books,' 星河 ')[0].id,'B-001');assert.equal(searchBooks(seed.books,' mAyA ')[0].id,'B-002');assert.equal(searchBooks(seed.books,'missing').length,0);});
test('AC-006/007/008/009/011 real file HTTP boundaries',async()=>{const {store}=await fixture();const {server,url}=await start(store);try{const original=await readFile(store.file,'utf8');for(const note of [' ','x'.repeat(121)])assert.equal((await patch(url,{note,revision:0,operationId:'invalid-input'})).status,400);assert.equal((await patch(url,{note:'valid',revision:0,operationId:'unknown-field',status:'borrowed'})).status,400);assert.equal((await patch(url,{note:'valid',revision:0,operationId:'wrong-origin'},{Origin:'http://evil.invalid'})).status,403);assert.equal(await readFile(store.file,'utf8'),original);const input={note:'HTTP 持久化',revision:0,operationId:'same-operation'};assert.equal((await patch(url,input)).status,200);assert.equal((await patch(url,input)).body.revision,1);const committed=await readFile(store.file,'utf8');assert.equal((await patch(url,{note:'conflict',revision:0,operationId:'stale-operation'})).status,409);assert.equal(await readFile(store.file,'utf8'),committed);assert.equal((await fetch(url+'/api/books/B-001/status',{method:'PATCH'})).status,404);store.failWrite=true;assert.equal((await patch(url,{note:'fail',revision:1,operationId:'fail-operation'})).status,503);assert.equal(await readFile(store.file,'utf8'),committed);for(const damaged of ['{broken',JSON.stringify({...seed,schemaVersion:99})]){await writeFile(store.file,damaged);assert.equal((await fetch(url+'/api/books')).status,503);assert.equal(await readFile(store.file,'utf8'),damaged);}await writeFile(store.file,committed);assert.equal((await fetch(url+'/api/books')).status,200);actions.push('API expected refusals: 400 invalid/unknown input; 403 Origin; 409 revision; 404 status endpoint; 503 failed write/corrupt schema. All unchanged-file assertions passed.');}finally{await stop(server);}});
test('AC-011 non-loopback startup rejected',async()=>{const p=spawn(process.execPath,['scripts/serve.mjs','--host','0.0.0.0','--port','0'],{stdio:['ignore','pipe','pipe']});let out='';p.stderr.on('data',v=>out+=v);const code=await new Promise(r=>p.on('exit',r));assert.equal(code,1);assert.match(out,/127.0.0.1/);});
test('AC-001..011 real offline browser, restart, keyboard, screenshots', {timeout:130000},async()=>{const require=createRequire(import.meta.url);const {chromium}=require('C:/Users/44725/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');const {store}=await fixture({delay:500});let {server,url}=await start(store);let browser,context;try{browser=await chromium.launch({headless:true});context=await browser.newContext({viewport:{width:1440,height:900}});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const external=[],unexpected=[],consoleErrors=[];await context.route('**/*',async route=>{const u=new URL(route.request().url());requests.push({url:u.href,method:route.request().method()});if(u.hostname!=='127.0.0.1'){external.push(u.href);return route.abort();}return route.continue();});const page=await context.newPage();page.on('console',m=>{if(m.type()==='error')consoleErrors.push(m.text());});page.on('pageerror',e=>consoleErrors.push(e.message));page.on('requestfailed',r=>unexpected.push(r.url()));let expectedFailure=false;page.on('response',r=>{if(r.status()>=400&&!expectedFailure)unexpected.push(`${r.status()} ${r.url()}`);});await page.goto(url);await page.locator('.book').nth(2).waitFor();assert.equal((await fetch(url+'/api/health')).status,200);assert.deepEqual(await (await fetch(url+'/api/health')).json(),{status:'ok',project:'offline-library-demo'});assert.deepEqual(await page.locator('.book').evaluateAll(rows=>rows.map(r=>r.dataset.id)),['B-001','B-002','B-003']);for(const b of seed.books){assert.ok((await page.locator(`[data-id="${b.id}"]`).innerText()).includes(b.title));assert.ok((await page.locator(`[data-id="${b.id}"]`).innerText()).includes(b.author));}assert.equal(await page.locator('#total').innerText(),'3');assert.equal(await page.locator('#available').innerText(),'2');assert.equal(await page.locator('#borrowed').innerText(),'1');assert.equal(await page.locator('.badge').filter({hasText:'可借'}).count(),2);assert.ok((await page.locator('body').innerText()).includes('无真实身份认证'));await page.screenshot({path:path.join(evidence,'desktop-1440x900.png'),fullPage:false});const beforeSearch=await readFile(store.file,'utf8');for(const [q,id] of [[' 星河 ','B-001'],[' mAyA ','B-002'],['周小','B-003']]){await page.locator('#search').fill(q);await page.locator('#search').press('Enter');await page.waitForFunction(id=>document.querySelectorAll('.book').length===1&&document.querySelector('.book').dataset.id===id,id);}await page.locator('#search').fill('不存在');await page.locator('#search').press('Enter');await page.getByText('没有找到匹配图书，请尝试其他关键词。').waitFor();await page.locator('#clear').click();await page.waitForFunction(()=>document.querySelectorAll('.book').length===3);assert.equal(await readFile(store.file,'utf8'),beforeSearch);await page.locator('#note').fill('取消的草稿');await page.locator('#save').click();await page.keyboard.press('Escape');assert.equal(await readFile(store.file,'utf8'),beforeSearch);assert.equal(await page.locator('#save').evaluate(e=>e===document.activeElement),true);for(const note of [' ','😀'.repeat(121)]){await page.locator('#note').fill(note);await page.locator('#save').click();assert.equal(await page.locator('#confirm').evaluate(e=>e.open),false);}await page.locator('#note').fill('浏览器确认持久化');await page.locator('#save').focus();await page.keyboard.press('Enter');await page.locator('#commit').focus();const beforeRequests=requests.filter(r=>r.method==='PATCH').length;await page.keyboard.press('Enter');await page.waitForFunction(()=>document.querySelector('#commit').disabled);assert.equal(await page.locator('#save').isDisabled(),true);await page.locator('#commit').evaluate(e=>{e.click();e.click();});await page.getByText('保存成功',{exact:true}).waitFor();assert.equal(requests.filter(r=>r.method==='PATCH').length-beforeRequests,1);await page.reload();await page.waitForFunction(()=>document.querySelector('#note').value==='浏览器确认持久化');const persisted=await store.read();assert.equal(persisted.books[0].revision,1);assert.equal(await page.locator('#record').getAttribute('data-revision'),'1');const apiBooks=await (await fetch(url+'/api/books')).json();assert.deepEqual(apiBooks.books,persisted.books);
// Stop and start a distinct owned server process on the same port, using the UI-written file.
const port=Number(new URL(url).port);await stop(server);server=null;const child=spawn(process.execPath,['scripts/serve.mjs','--host','127.0.0.1','--port',String(port)],{env:{...process.env,DEMO_DATA_DIR:store.dir},stdio:['ignore','pipe','pipe']});let runtime='';child.stdout.on('data',v=>runtime+=v);child.stderr.on('data',v=>runtime+=v);try{await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Restart timeout')),10000);child.stdout.on('data',v=>{if(v.toString().includes('Listening')){clearTimeout(timer);resolve();}});child.on('exit',c=>{clearTimeout(timer);reject(new Error('Restart exited '+c));});});await page.reload();await page.waitForFunction(()=>document.querySelector('#note').value==='浏览器确认持久化');assert.equal(await page.locator('#record').getAttribute('data-revision'),'1');}finally{child.kill();await new Promise(r=>child.on('exit',r));await writeFile(path.join(evidence,'runtime-restart.log'),runtime);}({server,url}=await start(store));await page.goto(url);await page.locator('.book').nth(2).waitFor();store.failWrite=true;const prior=await readFile(store.file,'utf8');await page.locator('#note').fill('失败保留草稿');await page.locator('#save').click();expectedFailure=true;await page.locator('#commit').click();await page.getByText('保存失败，草稿已保留，请重试',{exact:true}).waitFor();assert.equal(await page.locator('#note').inputValue(),'失败保留草稿');assert.equal(await readFile(store.file,'utf8'),prior);store.failWrite=false;expectedFailure=false;await page.locator('#reload').click();await page.waitForFunction(()=>document.querySelector('#note').value==='浏览器确认持久化');await page.setViewportSize({width:390,height:844});await page.screenshot({path:path.join(evidence,'mobile-390x844.png'),fullPage:false});for(const viewport of [{width:1440,height:900},{width:390,height:844}]){await page.setViewportSize(viewport);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);for(const id of ['search','note','save']){await page.locator('#'+id).scrollIntoViewIfNeeded();assert.equal(await page.locator('#'+id).isVisible(),true);}await page.locator('#search').focus();assert.equal(await page.locator('#search').evaluate(e=>getComputedStyle(e).outlineStyle),'solid');}assert.equal(external.length,0);assert.deepEqual(unexpected,[]);assert.deepEqual(consoleErrors,[]);assert.ok(requests.some(r=>r.url.endsWith('/style.css')));assert.ok(requests.some(r=>r.url.endsWith('/app.js')));actions.push('Browser: list/IDs/counts, title+author mixed-case search, empty+clear, cancel/Escape focus, invalid Unicode boundaries, delayed duplicate click, UI save/refresh, actual service process restart, failed write draft preservation, two viewports, no overflow, visible focus; no external attempts, unexpected HTTP/request errors or console errors.');await writeFile(path.join(evidence,'browser-errors.json'),JSON.stringify({external,unexpected,consoleErrors},null,2));}finally{if(context){await context.tracing.stop({path:path.join(evidence,'browser-trace.zip')});await context.close();}if(browser)await browser.close();if(server)await stop(server);await writeFile(path.join(evidence,'requests.json'),JSON.stringify(requests,null,2));await writeFile(path.join(evidence,'behavior.log'),actions.join('\n'));}});
test('AC-005 foreground contrast >=4.5:1',()=>{const lum=h=>{const rgb=h.match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722;};const pairs=[['172033','ffffff'],['526077','ffffff'],['2457c5','ffffff'],['196039','e7f4ed'],['80500c','fff0dc'],['526077','f5f7fa'],['2457c5','edf2ff']];const results=pairs.map(([f,b])=>({foreground:f,background:b,ratio:(Math.max(lum(f),lum(b))+.05)/(Math.min(lum(f),lum(b))+.05)}));for(const r of results)assert.ok(r.ratio>=4.5,JSON.stringify(r));return writeFile(path.join(evidence,'contrast.json'),JSON.stringify(results,null,2));});
